-- Reviewed links to the canonical planning task board. No automatic checklist conversion.
begin;
create table if not exists public.cb_experience_task_links(item_id uuid primary key references public.cb_experience_items on delete cascade,task_id uuid references public.cb_tasks on delete set null,revision bigint not null default 1,updated_at timestamptz not null default now());
create table if not exists public.cb_experience_task_writes(user_id uuid not null references auth.users on delete cascade,client uuid not null,payload jsonb not null,response jsonb not null,primary key(user_id,client));
create table if not exists public.cb_experience_task_history(item_id uuid not null references public.cb_experience_items on delete cascade,revision bigint not null,actor_id uuid not null references auth.users,snapshot jsonb not null,at timestamptz not null default now(),primary key(item_id,revision));
alter table public.cb_experience_task_links enable row level security;alter table public.cb_experience_task_writes enable row level security;alter table public.cb_experience_task_history enable row level security;
revoke all on public.cb_experience_task_links,public.cb_experience_task_writes,public.cb_experience_task_history from public,anon,authenticated;
create or replace function public.cb_experience_task_context(p_item uuid,p_search text default '') returns jsonb language plpgsql stable security definer set search_path='' as $$
declare i public.cb_experience_items;e public.cb_project_events;l public.cb_experience_task_links;t public.cb_tasks;begin
 select * into i from public.cb_experience_items where id=p_item;select * into e from public.cb_project_events where id=i.event_id;
 if i.id is null or not coalesce(public.cb_project_access(e.project_id,'write') and public.cb_experience_member(e.id,auth.uid()),false) then raise exception 'Celebration planning access required' using errcode='42501';end if;
 if p_search is null or length(p_search)>100 then raise exception 'Search using up to 100 characters';end if;
 select * into l from public.cb_experience_task_links where item_id=i.id;select * into t from public.cb_tasks where id=l.task_id and project_id=e.project_id and public.cb_task_visible(id);
 return jsonb_build_object('item',i.id,'item_revision',i.revision,'event',e.id,'event_revision',e.revision,'project',e.project_id,'title',i.data->>'title','cancelled',i.data->>'status'='Cancelled','revision',coalesce(l.revision,0),'task',case when t.id is null then null else jsonb_build_object('id',t.id,'title',t.title,'revision',t.revision,'due',t.due_date,'done',t.done,'approval_required',t.approval_required,'approved',t.approved_by is not null) end,'choices',(select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'title',x.title,'revision',x.revision,'done',x.done,'due',x.due_date) order by x.title,x.id),'[]') from (select * from public.cb_tasks where project_id=e.project_id and kind='task' and public.cb_task_visible(id) and strpos(lower(title),lower(p_search))>0 order by title,id limit 50) x),'people',(select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'name',coalesce(p.full_name,'Wedding collaborator')) order by p.full_name,x.id),'[]') from (select owner_id id from public.cb_projects where id=e.project_id union select user_id from public.cb_members where project_id=e.project_id) x left join public.cb_profiles p on p.user_id=x.id where public.cb_experience_member(e.id,x.id)));
end;$$;
create or replace function public.cb_save_experience_task(p_item uuid,p_item_revision bigint,p_event_revision bigint,p_revision bigint,p_client uuid,p_task uuid,p_task_revision bigint,p_new jsonb,p_confirm boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare i public.cb_experience_items;e public.cb_project_events;l public.cb_experience_task_links;t public.cb_tasks;w public.cb_experience_task_writes;payload jsonb;result jsonb;k text;recipient uuid;email text;ref text;due date;begin
 select * into i from public.cb_experience_items where id=p_item;select * into e from public.cb_project_events where id=i.event_id;perform 1 from public.cb_projects where id=e.project_id for update;select * into e from public.cb_project_events where id=i.event_id for update;
 if i.id is null or not coalesce(public.cb_project_access(e.project_id,'write') and public.cb_experience_member(e.id,auth.uid()),false) then raise exception 'Celebration planning access required' using errcode='42501';end if;
 payload=jsonb_build_object('item',p_item,'item_revision',p_item_revision,'event_revision',p_event_revision,'revision',p_revision,'task',p_task,'task_revision',p_task_revision,'new',p_new,'confirm',p_confirm);
 if p_client is null then raise exception 'Request ID required';end if;select * into w from public.cb_experience_task_writes where user_id=auth.uid() and client=p_client;if found then if w.payload is distinct from payload then raise exception 'Retry the original preparation task' using errcode='PT409';end if;return w.response;end if;
 if p_confirm is distinct from true then raise exception 'Review and confirm the shared planning task';end if;
 select * into i from public.cb_experience_items where id=p_item for update;if i.data->>'status'='Cancelled' then raise exception 'Reopen the cancelled experience before changing its task';end if;
 if i.revision is distinct from p_item_revision or e.revision is distinct from p_event_revision then raise exception 'The celebration or service changed. Refresh before linking a task.' using errcode='PT409';end if;
 select * into l from public.cb_experience_task_links where item_id=p_item for update;if coalesce(l.revision,0) is distinct from p_revision then raise exception 'Another teammate changed this task connection. Refresh first.' using errcode='PT409';end if;
 if p_new is not null then
 if p_task is not null or p_task_revision is not null or jsonb_typeof(p_new) is distinct from 'object' or p_new-array['title','description','due','assignee']::text[]<>'{}' then raise exception 'Choose an existing task or review a new one';end if;
 foreach k in array array['title','description','due','assignee'] loop if jsonb_typeof(p_new->k) is distinct from 'string' or length(p_new->>k)>(case when k='description' then 4000 else 300 end) then raise exception 'Review task text limits';end if;end loop;
 if length(btrim(p_new->>'title'))=0 then raise exception 'Add a task title';end if;
 recipient=(p_new->>'assignee')::uuid;if not public.cb_experience_member(e.id,recipient) then raise exception 'Choose an accepted collaborator with celebration access';end if;select u.email into email from auth.users u where u.id=recipient;if email is null then raise exception 'Choose a collaborator with an account email';end if;
 if p_new->>'due'<>'' then if p_new->>'due'!~'^\d{4}-\d{2}-\d{2}$' then raise exception 'Use a valid task due date';end if;due=(p_new->>'due')::date;end if;
 ref='experience-task:'||gen_random_uuid()::text;
 t=public.cb_save_board_task(e.project_id,ref,0,p_new->>'title',email,due,'task',p_new->>'description','{}',false,'');
 elsif p_task is not null then select * into t from public.cb_tasks where id=p_task and project_id=e.project_id and kind='task' and public.cb_task_visible(id) for update;if t.id is null then raise exception 'Choose an accessible task in this wedding' using errcode='42501';end if;if t.revision is distinct from p_task_revision then raise exception 'The task changed. Refresh before linking it.' using errcode='PT409';end if;
 elsif p_task_revision is not null then raise exception 'Clear the task revision when removing a connection';end if;
 insert into public.cb_experience_task_links(item_id,task_id) values(p_item,t.id) on conflict(item_id) do update set task_id=excluded.task_id,revision=public.cb_experience_task_links.revision+1,updated_at=now() returning * into l;
 insert into public.cb_experience_task_history values(l.item_id,l.revision,auth.uid(),to_jsonb(l),now());result=jsonb_build_object('saved',true,'revision',l.revision,'task',t.id);insert into public.cb_experience_task_writes values(auth.uid(),p_client,payload,result);return result;end;$$;
revoke all on function public.cb_experience_task_context(uuid,text),public.cb_save_experience_task(uuid,bigint,bigint,bigint,uuid,uuid,bigint,jsonb,boolean) from public,anon,authenticated;
grant execute on function public.cb_experience_task_context(uuid,text),public.cb_save_experience_task(uuid,bigint,bigint,bigint,uuid,uuid,bigint,jsonb,boolean) to authenticated;
notify pgrst,'reload schema';commit;
